def robust_move():
    total_moved = 0
    # We'll use a set to keep track of IDs we've already processed in this session 
    # to avoid infinite loops if the stage doesn't change.
    processed_ids = set()

    while True:
        accounts = query_accounts(segment='smb', stage='lead', limit=50, offset=0)
        if not accounts:
            break

        # Check if accounts is a list of dicts or just a dict
        if isinstance(accounts, dict):
            # Some APIs return { 'results': [...] }
            accounts = accounts.get('results', [])

        if not accounts:
            break

        batch_ids = []
        for acc in accounts:
            acc_id = acc.get('id')
            if acc_id and acc_id not in processed_ids:
                batch_ids.append(acc_id)

        if not batch_ids:
            # We've seen all these IDs before and they are still in 'lead' stage
            break

        for acc_id in batch_ids:
            update_account(account_id=acc_id, stage='trial')
            processed_ids.add(acc_id)
            total_moved += 1

        if len(accounts) < 50:
            break

    return total_moved

