    if isinstance(issues_data, dict):
        # Try to find the list in the dict if it's not a direct list
        issues = issues_data.get('issues', [])
    else:
        issues = issues_data

    assignees = []
    for issue in issues:
        assignee_id = issue.get('assignee')
        if assignee_id:
